let currentWorkflow=[],activeReplaceIndex=null,currentTemplate='general',slotTimer=null;
function logo(t,size='normal'){
  const path=t.icon?ICONS[t.icon]:null;
  if(path) return `<span class="logo-box" style="background:${t.bg};color:${t.fg}"><svg viewBox="0 0 24 24" aria-hidden="true" fill="currentColor"><path d="${path}"></path></svg></span>`;
  return `<span class="logo-box" style="background:${t.bg};color:${t.fg}"><span class="custom-logo">${escapeHtml(t.mark||t.name.slice(0,2))}</span></span>`;
}
function tags(t){let x='';const cls=t.pricing==='free'?'free':t.pricing==='paid'?'paid':'freemium';x+=`<span class="tag ${cls}">${t.pricing==='free'?'FREE':t.pricing==='paid'?'PAID':'FREEMIUM'}</span>`;if(t.open)x+='<span class="tag open">OPEN SOURCE</span>';if(t.wdwPaid)x+='<span class="tag wdwpaid">WDW PICK</span>';return x}
function renderBoard(){const board=document.getElementById('toolBoard');board.innerHTML=categories.map(c=>{const set=tools.filter(t=>t.category===c.id);return `<div class="tool-row"><div class="cat"><b>${c.name}</b><span>${c.sub}</span></div><div class="tools">${set.map(t=>`<article class="tool-tile ${t.preferred?'preferred':''}" tabindex="0" data-tool="${t.id}"><div class="tile-top">${logo(t)}<div class="tool-name">${t.name}</div></div><div class="tool-desc">${t.desc}</div><div class="tags">${tags(t)}</div><div class="tile-actions"><button data-info="${t.id}">INFO</button><a href="${t.url}" target="_blank" rel="noopener">OPEN ↗</a></div></article>`).join('')}</div></div>`}).join('');document.getElementById('toolCount').textContent=tools.length;document.querySelectorAll('[data-info]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();openDetail(b.dataset.info)}));document.querySelectorAll('.tool-tile').forEach(card=>{card.addEventListener('dblclick',()=>openTool(card.dataset.tool));card.addEventListener('click',e=>{if(e.target.closest('.tile-actions'))return;openDetail(card.dataset.tool)})})}
function analyzePrompt(text){
  const s=text.toLowerCase();
  const tests=[
    ['Video',/video|youtube|documentary|short|reel|tiktok|film|motion/],
    ['Visuals',/image|visual|graphic|cover|thumbnail|slide|presentation|art|photo/],
    ['Voice',/voice|narrat|voiceover|spoken|podcast|audio/],
    ['Music',/music|song|soundtrack|background music|instrumental/],
    ['Website / App',/website|web site|landing page|app|html|interactive|software|calculator|tool/],
    ['Learning',/lesson|course|teaching|teacher|student|worksheet|curriculum|education|classroom/],
    ['Sell',/sell|sales|etsy|gumroad|product|store|shop|listing|customer/],
    ['Marketing',/market|campaign|social media|promotion|promote|newsletter|email marketing|repurpose|lead/],
    ['Automation',/automat|workflow|trigger|webhook|hands[- ]?off|repeat/],
    ['Storage',/store|storage|drive|archive|master file|version/],
    ['Analytics',/analytics|measure|track|performance|traffic|conversion|retention|seo|search/],
    ['Pinterest',/pinterest/],['YouTube',/youtube/],['TikTok',/tiktok/],['Email',/email|newsletter/]
  ];
  const signals=tests.filter(([,re])=>re.test(s)).map(([name])=>name);
  const strengths=[];
  const add=(...x)=>x.forEach(v=>!strengths.includes(v)&&strengths.push(v));
  if(/research|fact|source|history|information|compare|analy/.test(s))add('research','analysis');
  if(/write|script|copy|article|caption|description/.test(s))add('writing','script');
  if(/lesson|teacher|student|curriculum|classroom|education/.test(s))add('lesson','education');
  if(/slide|presentation|powerpoint/.test(s))add('slides','presentation','design');
  if(/image|visual|graphic|cover|thumbnail|art|photo/.test(s))add('image','design','graphics');
  if(/voice|narrat|voiceover|spoken|podcast|audio/.test(s))add('voice','narration');
  if(/music|song|soundtrack|instrumental/.test(s))add('music');
  if(/video|youtube|documentary|short|reel|tiktok|film/.test(s))add('video','edit');
  if(/website|web site|landing page/.test(s))add('website','code');
  if(/app|interactive|software|calculator|tool/.test(s))add('app','code');
  if(/automat|workflow|trigger|webhook/.test(s))add('automation','workflow');
  if(/store|storage|drive|archive|master/.test(s))add('files','storage');
  if(/market|campaign|promotion|promote|newsletter|email marketing|repurpose|lead/.test(s))add('marketing');
  if(/email|newsletter/.test(s))add('email');
  if(/publish|youtube|pinterest|tiktok|audience|distribut/.test(s))add('publish','audience','social');
  if(/pinterest/.test(s))add('pinterest');
  if(/sell|sales|etsy|gumroad|store|shop|listing/.test(s))add('sell','products');
  if(/analytics|measure|track|traffic|conversion|retention/.test(s))add('analytics','traffic');
  if(/seo|search/.test(s))add('seo','search');
  if(/youtube/.test(s))add('youtube');
  return {signals:signals.slice(0,8),strengths};
}
function pickTemplate(text){
  const s=text.toLowerCase();
  const scores={video:0,website:0,lesson:0,product:0,marketing:0,audio:0,general:1};
  const hit=(key,re,pts=3)=>{const m=s.match(re);if(m)scores[key]+=pts+(m.length>1?1:0)};
  hit('lesson',/lesson|course|teaching|teacher|student|worksheet|powerpoint|slides|curriculum|education|classroom/g,4);
  hit('website',/website|web site|landing page|app|html|interactive|software|calculator|web tool/g,4);
  hit('audio',/podcast|voice|narration|audio|music|song|voiceover/g,3);
  hit('marketing',/market|campaign|social media|promotion|promote|seo|lead|newsletter|email marketing|repurpose/g,4);
  hit('product',/etsy|digital product|ebook|template|sell|store|listing|gumroad/g,4);
  hit('video',/video|youtube|documentary|short|reel|tiktok|film/g,4);
  if(scores.audio>1&&scores.video>1)scores.video+=2;
  return Object.entries(scores).sort((a,b)=>b[1]-a[1])[0][0];
}
function adaptSteps(temp,prompt){
  const analysis=analyzePrompt(prompt),s=prompt.toLowerCase();
  let steps=temp.steps.map(x=>[x[0],x[1],[...x[2]],x[3],x[4]]);
  const has=cat=>steps.some(x=>x[1]===cat);
  const addStep=(entry)=>{if(!has(entry[1]))steps.push(entry)};
  if((/voice|narrat|voiceover|podcast|audio|music|soundtrack/.test(s))) addStep(['Create Audio','audio',['voice','narration','music'],'Create the requested voice, music or sound layer before final assembly.',false]);
  if((/video|youtube|documentary|short|reel|tiktok|film/.test(s))) addStep(['Edit / Assemble Video','video',['video','edit'],'Assemble motion, captions, timing and final delivery formats.',false]);
  if((/automat|workflow|trigger|webhook|hands[- ]?off|repeat/.test(s))) addStep(['Automate Repeats','automate',['automation','workflow'],'Connect repeatable handoffs so the project requires less manual file-moving.',true]);
  if((/store|storage|archive|master|drive|version|reusable/.test(s))) addStep(['Organize Masters','organize',['files','storage'],'Preserve reusable masters, versions and delivery files in a dependable structure.',true]);
  if((/publish|youtube|pinterest|tiktok|etsy|gumroad|sell|sales|audience|social|newsletter|email/.test(s))) addStep(['Publish / Distribute','publish',['publish','social','sell','audience'],'Move the finished work into the channels named in the project request.',true]);
  if((/analytics|measure|track|traffic|conversion|retention|performance|seo|search/.test(s))) addStep(['Measure Results','measure',['analytics','traffic','seo'],'Track the signals that show whether the finished work is reaching its goal.',true]);
  const order={think:1,visual:2,audio:3,video:4,build:5,automate:6,organize:7,publish:8,measure:9};
  steps.sort((a,b)=>order[a[1]]-order[b[1]]);
  return {steps,analysis};
}
function scoreTool(t,strengths,mode,preferMine,promptStrengths=[]){let score=0;strengths.forEach(s=>{if(t.strengths.includes(s))score+=5});promptStrengths.forEach(s=>{if(t.strengths.includes(s))score+=9});if(preferMine&&t.preferred)score+=4;if(mode==='free'){if(t.freeUsable)score+=8;else score-=100;if(t.open)score+=4}else if(mode==='mixed'){if(t.freeUsable)score+=2;if(t.open)score+=2;if(t.preferred)score+=1.5}else if(mode==='all'&&t.preferred)score+=1;const idx=tools.filter(x=>x.category===t.category).indexOf(t);score+=Math.max(0,8-idx)*.35;return score}
function chooseTool(category,strengths,mode,preferMine,promptStrengths=[]){let c=tools.filter(t=>t.category===category);if(mode==='free')c=c.filter(t=>t.freeUsable);c.sort((a,b)=>scoreTool(b,strengths,mode,preferMine,promptStrengths)-scoreTool(a,strengths,mode,preferMine,promptStrengths));return c[0]||tools.find(t=>t.category===category)}
function selectionReason(w,mode){const hits=w.strengths.filter(x=>w.tool.strengths.includes(x)).slice(0,3);const parts=[];if(hits.length)parts.push(`matches ${hits.join(' + ')}`);if(w.tool.preferred)parts.push('WDW pick');if(mode==='free'&&w.tool.freeUsable)parts.push('$0-capable');else if(w.tool.open)parts.push('open source');return parts.length?`Selected because it ${parts.join(' · ')}.`:'Selected as the strongest fit in this production role.'}
function buildWorkflow(){const prompt=document.getElementById('projectPrompt').value.trim();if(!prompt){toast('Describe the project first.');return}const mode=document.querySelector('input[name="mode"]:checked').value,preferMine=document.getElementById('preferMine').checked;currentTemplate=pickTemplate(prompt);const temp=templates[currentTemplate];const adapted=adaptSteps(temp,prompt);currentWorkflow=adapted.steps.map(([step,category,strengths,why,auto])=>({step,category,strengths:[...new Set([...strengths,...adapted.analysis.strengths])],why,auto,done:false,tool:chooseTool(category,strengths,mode,preferMine,adapted.analysis.strengths)}));renderWorkflow(temp,mode,adapted.analysis)}
function renderWorkflow(temp=templates[currentTemplate],mode=null,analysis=null){const shell=document.getElementById('workflowShell');shell.classList.add('active');document.getElementById('workflowTitle').textContent=temp.title;const activeMode=mode||document.querySelector('input[name="mode"]:checked').value;const modeName={all:'Best available',free:'Free-only',mixed:'Free + paid mix'}[activeMode];document.getElementById('workflowNote').textContent=`${modeName} · Open each tool when you reach that step · Replace any node without rebuilding the entire path.`;const free=currentWorkflow.filter(w=>w.tool.freeUsable).length,wdw=currentWorkflow.filter(w=>w.tool.preferred).length,auto=currentWorkflow.filter(w=>w.auto).length;document.getElementById('workflowStats').innerHTML=`<span class="stat"><b>${currentWorkflow.length}</b> steps</span><span class="stat"><b>${free}</b> $0-capable</span><span class="stat"><b>${wdw}</b> recommended picks</span><span class="stat"><b>${auto}</b> automation candidates</span>`;document.getElementById('projectDNA').innerHTML=temp.dna.map(x=>`<span>${x}</span>`).join('');
  const prompt=document.getElementById('projectPrompt').value.trim();const a=analysis||analyzePrompt(prompt);const readout=document.getElementById('projectReadout');const signals=a.signals.length?a.signals:['General creation'];readout.classList.add('active');readout.innerHTML=`<div><div class="readout-label">Project readout</div><div class="readout-title">${escapeHtml(temp.title.replace(' Workflow',''))}</div><div class="readout-copy">The engine detected these requirements and used them to add stages and weight tool selection.</div></div><div class="readout-signals">${signals.map(x=>`<span class="readout-chip">${escapeHtml(x)}</span>`).join('')}</div>`;
  document.getElementById('workflow').innerHTML=currentWorkflow.map((w,i)=>`${i?'<div class="arrow"></div>':''}<article class="step ${w.done?'done':''}" style="animation-delay:${i*.05}s"><div class="step-num">STEP ${String(i+1).padStart(2,'0')} · ${categories.find(c=>c.id===w.category).name.replace(/^\d+ · /,'')}</div><div class="step-title">${w.step}</div><div class="step-tool">${logo(w.tool)}<div><b>${w.tool.name}</b><span>${w.tool.pricing.toUpperCase()}${w.tool.open?' · OPEN SOURCE':''}${w.tool.preferred?' · WDW PICK':''}</span></div></div><div class="why">${w.why}</div><div class="selection-note"><b>WHY THIS TOOL</b> · ${selectionReason(w,activeMode)}</div><div class="node-actions"><button class="open" data-open="${i}">OPEN ↗</button><button data-replace="${i}">REPLACE</button><button data-done="${i}">${w.done?'UNDO':'DONE'}</button></div></article>`).join('');document.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',()=>openTool(currentWorkflow[+b.dataset.open].tool.id)));document.querySelectorAll('[data-replace]').forEach(b=>b.addEventListener('click',()=>openReplace(+b.dataset.replace)));document.querySelectorAll('[data-done]').forEach(b=>b.addEventListener('click',()=>{currentWorkflow[+b.dataset.done].done=!currentWorkflow[+b.dataset.done].done;renderWorkflow(temp,activeMode,a)}));shell.scrollIntoView({behavior:'smooth',block:'nearest'})}
function startSlots(){const strip=document.getElementById('slotStrip'),slots=document.getElementById('slots');strip.classList.add('on');const pool=tools.filter(t=>['think','visual','audio','video','build','automate'].includes(t.category));let n=0;clearInterval(slotTimer);slotTimer=setInterval(()=>{n++;slots.innerHTML=Array.from({length:5},(_,i)=>{const t=pool[(n*3+i*7)%pool.length];return `<div class="slot">${logo(t)}<span>${t.name}</span></div>`}).join('')},75)}
function shuffleAndBuild(){const btn=document.getElementById('buildBtn');btn.disabled=true;btn.innerHTML='<span class="spark">✦</span>ASSEMBLING…';startSlots();setTimeout(()=>{clearInterval(slotTimer);buildWorkflow();document.getElementById('slotStrip').classList.remove('on');btn.disabled=false;btn.innerHTML='<span class="spark">✦</span>BUILD WORKFLOW'},950)}
function openReplace(index){activeReplaceIndex=index;const item=currentWorkflow[index],mode=document.querySelector('input[name="mode"]:checked').value;let c=tools.filter(t=>t.category===item.category&&t.id!==item.tool.id);if(mode==='free')c=c.filter(t=>t.freeUsable);c.sort((a,b)=>scoreTool(b,item.strengths,mode,false)-scoreTool(a,item.strengths,mode,false));document.getElementById('replaceTitle').textContent=`Replace ${item.tool.name}`;document.getElementById('replaceSubtitle').textContent=`Step ${index+1}: ${item.step}. Alternatives stay inside the same production role so the workflow still makes sense.`;document.getElementById('replaceList').innerHTML=c.map((t,i)=>`<button class="replace-option" data-choice="${i}">${logo(t)}<span class="meta"><b>${t.name}</b><span>${t.desc}</span><span>${t.pricing.toUpperCase()}${t.open?' · OPEN SOURCE':''}${t.preferred?' · WDW PICK':''}</span></span></button>`).join('')||'<div style="padding:12px">No alternatives match this filter.</div>';document.querySelectorAll('[data-choice]').forEach(b=>b.addEventListener('click',()=>{currentWorkflow[activeReplaceIndex].tool=c[+b.dataset.choice];document.getElementById('replaceDialog').close();renderWorkflow();toast('Workflow step replaced.')}));document.getElementById('replaceDialog').showModal()}
function openTool(id){const t=tools.find(x=>x.id===id);if(t)window.open(t.url,'_blank','noopener')}
function openDetail(id){const t=tools.find(x=>x.id===id);if(!t)return;const experiments=JSON.parse(localStorage.getItem('wdwExperiments')||'[]'),isExp=experiments.includes(t.id);document.getElementById('detailBody').innerHTML=`<div class="detail-hero">${logo(t)}<div><h4>${t.name}</h4><div class="tags">${tags(t)}${t.preferred?'<span class="tag wdwpaid">WDW PICK</span>':''}</div></div></div><div class="detail-grid"><div class="detail-card"><b>What it does</b><p>${t.desc}</p></div><div class="detail-card"><b>Best-fit signals</b><p>${t.strengths.map(x=>x.replace(/\b\w/g,m=>m.toUpperCase())).join(' · ')||'General use'}</p></div><div class="detail-card"><b>Cost logic</b><p>${t.freeUsable?'Can be started or used at $0. ':''}${t.pricing==='freemium'?'Higher limits/features may require payment. ':t.pricing==='paid'?'Treat this as a paid-production choice. ':''}${t.open?'Open-source option: the exact license still matters for commercial use.':''}</p></div><div class="detail-card"><b>Command Center status</b><p>${t.preferred?'Part of the current WDW recommended stack or regular workflow.':'Alternative or specialist tool. It should prove a meaningful advantage before becoming a default.'}</p></div></div><div class="detail-actions"><a class="primary-link" href="${t.url}" target="_blank" rel="noopener">Open ${t.name} ↗</a><button id="experimentBtn">${isExp?'Remove from Experiments':'Add to Experiments'}</button></div>`;document.getElementById('detailDialog').showModal();document.getElementById('experimentBtn').addEventListener('click',()=>toggleExperiment(t.id))}
function toggleExperiment(id){let a=JSON.parse(localStorage.getItem('wdwExperiments')||'[]');if(a.includes(id))a=a.filter(x=>x!==id);else a.unshift(id);localStorage.setItem('wdwExperiments',JSON.stringify(a.slice(0,20)));document.getElementById('detailDialog').close();toast(a.includes(id)?'Added to Experiments.':'Removed from Experiments.')}
function saveWorkflow(){if(!currentWorkflow.length){toast('Build a workflow first.');return}const p=document.getElementById('projectPrompt').value.trim(),mode=document.querySelector('input[name="mode"]:checked').value,analysis=analyzePrompt(p);let list=JSON.parse(localStorage.getItem('wdwSavedWorkflows')||'[]');list.unshift({id:Date.now(),prompt:p,date:new Date().toLocaleDateString(),template:currentTemplate,mode,signals:analysis.signals,steps:currentWorkflow.map(w=>({step:w.step,tool:w.tool.name,id:w.tool.id,category:w.category}))});localStorage.setItem('wdwSavedWorkflows',JSON.stringify(list.slice(0,15)));toast('Workflow saved on this device.')}
const dictionary={'API':'A doorway that lets one piece of software talk directly to another. It is how an automation can ask a service to do work without you clicking through its website.','Automation':'A rule that says: when this happens, do these next steps automatically. It moves repeated work between apps.','AI Model':'The underlying AI engine that processes instructions and generates text, images, audio, video or predictions.','Open Source':'Software whose source code is available under a license that permits defined forms of use, study and modification. The exact license still matters.','Self-hosted':'Software you run on a computer or server you control instead of relying entirely on the vendor’s hosted service.','Token':'A small unit of text processed by a language model. Some services calculate usage or cost from tokens.','Workflow':'The ordered path a project follows from idea to finished output.','Agent':'An AI-powered system that can choose or execute several steps toward a goal, often using tools or external services.','Webhook':'An automatic message one app sends another when a specific event happens, such as a form submission.','Trigger':'The event that starts an automation — for example, a new file appearing in a folder.','Action':'The thing the automation does after a trigger — for example, send an email or create a record.'};
const freeMap={canva:['gptimage','comfyui'],elevenlabs:['chatterbox','kokoro'],capcut:['kdenlive','canvavideo'],chatgpt:['gemini','notebooklm'],github:['replit'],drive:['sheets','notion']};
function showModule(type){const d=document.getElementById('moduleDrawer');if(type==='dictionary'){d.innerHTML=`<div class="drawer-title">AI Dictionary</div><div class="drawer-sub">Enough technical language to understand your workflow — not a computer-science textbook.</div><div class="dictionary">${Object.entries(dictionary).map(([k,v])=>`<div class="term"><b>${k}</b><p>${v}</p></div>`).join('')}</div>`}else if(type==='saved'){const list=JSON.parse(localStorage.getItem('wdwSavedWorkflows')||'[]');d.innerHTML=`<div class="drawer-title">Saved Workflows</div><div class="drawer-sub">Saved locally on this device.</div><div style="margin-top:12px">${list.length?list.map(x=>`<div class="list-card"><div><b>${escapeHtml(x.prompt.slice(0,95))}${x.prompt.length>95?'…':''}</b><br><span>${x.date}</span></div><span class="route">${x.steps.map(s=>s.tool).join(' → ')}</span></div>`).join(''):'<div class="radar-note">No saved workflows yet. Build one above and press Save Workflow.</div>'}</div>`}else if(type==='alternatives'){const core=['canva','elevenlabs','capcut','chatgpt'];d.innerHTML=`<div class="drawer-title">Free Alternatives</div><div class="drawer-sub">These are not automatic replacements. They are the first zero-cost candidates worth testing when savings matter.</div><div style="margin-top:12px">${core.map(id=>{const src=tools.find(t=>t.id===id),alts=(freeMap[id]||[]).map(a=>tools.find(t=>t.id===a)).filter(Boolean);return `<div class="list-card"><div style="display:flex;align-items:center;gap:8px">${logo(src)}<div><b>${src.name}</b><br><span>Current / preferred route</span></div></div><span class="route">${alts.map(a=>a.name).join(' · ')||'No direct replacement'}</span></div>`}).join('')}</div>`}else if(type==='automation'){d.innerHTML=`<div class="drawer-title">Automation Map</div><div class="drawer-sub">Automation should remove repetitive handoffs, not automate judgment that still benefits from you.</div>${currentWorkflow.length?`<div style="margin-top:12px">${currentWorkflow.map(w=>`<div class="list-card"><div><b>${w.step}</b><br><span>${w.tool.name}</span></div><span class="route">${w.auto?'AUTOMATION CANDIDATE':'KEEP HUMAN-IN-THE-LOOP'}</span></div>`).join('')}</div>`:'<div class="radar-note">Build a workflow first. This map will then identify which steps are candidates for Activepieces, n8n, Make or another automation layer.</div>'}` }else if(type==='cost'){d.innerHTML=`<div class="drawer-title">Cost Center</div><div class="drawer-sub">The first job is preventing duplicate subscriptions — not calculating pennies before the workflow is stable.</div><div style="margin-top:12px"><div class="list-card"><div><b>Canva</b><br><span>WDW reference-stack anchor</span></div><span class="route">Design · slides · graphics · some video</span></div><div class="list-card"><div><b>ElevenLabs</b><br><span>WDW reference-stack anchor</span></div><span class="route">Final narration · voice</span></div><div class="list-card"><div><b>CapCut</b><br><span>WDW reference-stack anchor</span></div><span class="route">Editing · captions · social video</span></div></div><div class="radar-note">Before adding another paid creative tool, compare it against these anchors for duplicate capability and a clear workflow advantage.</div>`}else if(type==='radar'){d.innerHTML=`<div class="drawer-title">New Tool Radar</div><div class="drawer-sub">Research gate: only interrupt the workflow for meaningful changes.</div><div class="radar-note"><b>Current snapshot reviewed September 21, 2026.</b><br>Recommendations are intentionally conservative: a new tool is promoted only when it meaningfully saves money, saves time, improves quality, automates work, or creates revenue potential.</div>`}else if(type==='lab'){const candidates=tools.filter(t=>!t.preferred).slice(0,12);d.innerHTML=`<div class="drawer-title">Tool Lab</div><div class="drawer-sub">Candidates stay here until they prove they deserve a permanent place in the preferred stack.</div><div style="margin-top:12px">${candidates.map(t=>`<div class="list-card"><div style="display:flex;gap:8px;align-items:center">${logo(t)}<div><b>${t.name}</b><br><span>${t.category.toUpperCase()}</span></div></div><span class="route">${t.open?'OPEN SOURCE · ':''}${t.pricing.toUpperCase()}</span></div>`).join('')}</div>`}else if(type==='experiments'){const ids=JSON.parse(localStorage.getItem('wdwExperiments')||'[]'),arr=ids.map(id=>tools.find(t=>t.id===id)).filter(Boolean);d.innerHTML=`<div class="drawer-title">Experiments</div><div class="drawer-sub">Add a tool from its Info panel. A new tool becomes a default only after it proves a meaningful advantage.</div><div style="margin-top:12px">${arr.length?arr.map(t=>`<div class="list-card"><div style="display:flex;gap:8px;align-items:center">${logo(t)}<div><b>${t.name}</b><br><span>${t.desc}</span></div></div><span class="route">TEST</span></div>`).join(''):'<div class="radar-note">No experiments pinned yet. Open a tool’s Info panel and choose Add to Experiments.</div>'}</div>`}d.classList.add('active');d.scrollIntoView({behavior:'smooth',block:'nearest'})}
function escapeHtml(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.classList.remove('show'),1800)}
[...document.querySelectorAll('.mode')].forEach(label=>label.addEventListener('click',()=>{document.querySelectorAll('.mode').forEach(x=>x.classList.remove('selected'));label.classList.add('selected')}));
document.querySelectorAll('.example').forEach(b=>b.addEventListener('click',()=>{document.getElementById('projectPrompt').value=b.dataset.example;document.getElementById('projectPrompt').focus()}));
document.getElementById('buildBtn').addEventListener('click',shuffleAndBuild);document.getElementById('rebuildBtn').addEventListener('click',shuffleAndBuild);document.getElementById('saveBtn').addEventListener('click',saveWorkflow);document.getElementById('resetDoneBtn').addEventListener('click',()=>{currentWorkflow.forEach(w=>w.done=false);renderWorkflow()});document.getElementById('heroBuild').addEventListener('click',()=>document.getElementById('engine').scrollIntoView({behavior:'smooth'}));document.getElementById('heroTools').addEventListener('click',()=>document.getElementById('tools').scrollIntoView({behavior:'smooth'}));document.querySelectorAll('.module').forEach(m=>m.addEventListener('click',()=>showModule(m.dataset.module)));document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>document.getElementById(b.dataset.close).close()));

// Build 5 navigation, mobile menu, and cursor smudge.
const topbar=document.getElementById('top');
function syncWDWChrome(){
  topbar.classList.toggle('scrolled',window.scrollY>36);
}
window.addEventListener('scroll',syncWDWChrome,{passive:true});
syncWDWChrome();

const menuToggle=document.getElementById('menuToggle');
const siteNav=document.getElementById('siteNav');
if(menuToggle&&siteNav){
  const setMenu=open=>{topbar.classList.toggle('menu-open',open);menuToggle.setAttribute('aria-expanded',String(open));menuToggle.setAttribute('aria-label',open?'Close navigation':'Open navigation')};
  menuToggle.addEventListener('click',()=>setMenu(!topbar.classList.contains('menu-open')));
  siteNav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>setMenu(false)));
  document.addEventListener('click',e=>{if(topbar.classList.contains('menu-open')&&!topbar.contains(e.target))setMenu(false)});
  window.addEventListener('resize',()=>{if(window.innerWidth>820)setMenu(false)},{passive:true});
}

const cursorSmudge=document.getElementById('cursorSmudge');
if(cursorSmudge&&window.matchMedia('(pointer:fine)').matches){
  let tx=window.innerWidth/2,ty=window.innerHeight/2,cx=tx,cy=ty,raf=0;
  const draw=()=>{cx+=(tx-cx)*.16;cy+=(ty-cy)*.16;cursorSmudge.style.left=`${cx}px`;cursorSmudge.style.top=`${cy}px`;raf=requestAnimationFrame(draw)};
  window.addEventListener('mousemove',e=>{tx=e.clientX;ty=e.clientY;cursorSmudge.classList.add('on');if(!raf)draw()},{passive:true});
  window.addEventListener('mouseleave',()=>cursorSmudge.classList.remove('on'));
}

const musicToggle=document.getElementById('musicToggle');
const backgroundMusic=document.getElementById('backgroundMusic');
if(musicToggle&&backgroundMusic){
  const syncMusic=()=>{
    const on=!backgroundMusic.paused;
    musicToggle.setAttribute('aria-pressed',String(on));
    musicToggle.classList.toggle('music-on',on);
    musicToggle.title=on?'Turn music off':'Turn music on';
    musicToggle.setAttribute('aria-label',musicToggle.title);
  };
  musicToggle.addEventListener('click',async()=>{
    if(backgroundMusic.paused){
      try{ if(backgroundMusic.readyState<2) backgroundMusic.load(); await backgroundMusic.play(); }catch(e){ toast('Tap again if your browser blocked audio playback.'); }
    }else{ backgroundMusic.pause(); }
    syncMusic();
  });
  ['play','pause','ended'].forEach(ev=>backgroundMusic.addEventListener(ev,syncMusic));
  syncMusic();
}
const methodBtn=document.getElementById('methodBtn');
if(methodBtn) methodBtn.addEventListener('click',()=>document.getElementById('methodology').scrollIntoView({behavior:'smooth',block:'center'}));
renderBoard();
